def read_number(n: int) -> str:
    if n == 0:
        return '영'

    digits = ['', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']
    units_small = ['', '십', '백', '천']

    def read_four_digits(num):
        """Read a 4-digit number (0-9999)"""
        if num == 0:
            return ''

        result = ''
        for i in range(4):
            digit = (num // (10 ** (3 - i))) % 10
            if digit != 0:
                if i < 3:  # 천, 백, 십 positions
                    if digit == 1:
                        result += units_small[3 - i]
                    else:
                        result += digits[digit] + units_small[3 - i]
                else:  # ones position
                    result += digits[digit]

        return result

    # Split into groups: ones, 만 (10^4), 억 (10^8)
    ones = n % 10000
    mans = (n // 10000) % 10000
    eoks = (n // 100000000) % 10000

    result = ''

    # Add 억 group if non-zero
    if eoks > 0:
        result += read_four_digits(eoks) + '억'

    # Add 만 group if non-zero
    if mans > 0:
        man_str = read_four_digits(mans)
        if mans == 1:
            # Special case: exactly 1 in 만 group reads as just 만
            result += '만'
        else:
            result += man_str + '만'

    # Add ones group if non-zero
    if ones > 0:
        result += read_four_digits(ones)

    return result
